def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        text = data.decode("utf-8")
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        traces = parse_document(text)
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    text = None
    data = None
    try:
        out = []
        for (tid, cfg, events) in traces:
            rp = Replay(tid, cfg, events)
            rp.run()
            out.append(rp.result())
        traces = None
        doc = json.dumps({"version": 1, "results": out},
                         separators=(",", ":"))
    except Exception as exc:            # defensive: never crash silently
        sys.stderr.write("internal error: %r\n" % (exc,))
        sys.stdout.write(INVALID_OUT)
        return 0
    sys.stdout.write(doc)
    return 0


if __name__ == "__main__":
    sys.exit(main())
